<?php require_once __DIR__.'/../../classes/Database.php';require_once __DIR__.'/../../classes/Session.php';require_once __DIR__.'/../../classes/AdminAuth.php';Session::start();AdminAuth::requireLogin();$p=(new Database())->getConnection();$s=$p->query('SELECT id,libelle FROM secteur ORDER BY libelle')->fetchAll();$v=$p->query('SELECT id,libelle FROM ville ORDER BY libelle')->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$q=$p->prepare('INSERT INTO entreprise(nom,email,telephone,adresse,id_secteur,id_ville) VALUES(:n,:e,:t,:a,:s,:v)');$q->execute(['n'=>trim($_POST['nom']),'e'=>trim($_POST['email'])?:null,'t'=>trim($_POST['telephone'])?:null,'a'=>trim($_POST['adresse'])?:null,'s'=>(int)$_POST['id_secteur'],'v'=>(int)$_POST['id_ville']]);header('Location: index.php');exit;}?><!doctype html><html lang="fr"><body><h1>Ajouter entreprise</h1><form method="post"><input name="nom" placeholder="Nom" required><input name="email" type="email"><input name="telephone"><input name="adresse"><select name="id_secteur" required><?php foreach($s as $x):?><option value="<?=$x['id']?>"><?=htmlspecialchars($x['libelle'])?></option><?php endforeach;?></select><select name="id_ville" required><?php foreach($v as $x):?><option value="<?=$x['id']?>"><?=htmlspecialchars($x['libelle'])?></option><?php endforeach;?></select><button>Enregistrer</button></form></body></html>